/// Generic PerfectHash.pm hash: two rolling hashes index into h[].
#[inline]
fn perfect_hash(key: &[u8], h: &[int16], a0: u32, b0: u32, ma: u32, mb: u32, n: u32) -> i32 {
    let mut a = a0; let mut b = b0;
    for &c in key {
        a = a.wrapping_mul(ma).wrapping_add(c as u32);
        b = b.wrapping_mul(mb).wrapping_add(c as u32);
    }
    h[(a % n) as usize] as i32 + h[(b % n) as usize] as i32
}

